import type { EditorialEntry } from './types';

// Britain's most disgraced politicians — a ranked roundup of the scandals
// that ended careers and shook governments. Each politician is added one at a
// time as fed by the editor and fact-checked against public sources (BBC,
// Guardian, FT, Hansard, court reports, official inquiries) before the entry
// is committed. Current MPs carry a `memberId` so the name links to their
// /mps/<id> profile; historical figures omit it.

const piece: EditorialEntry = {
  slug: 'britains-most-disgraced-politicians',
  kicker: 'Investigation',
  headline: "Britain's Most Disgraced Politicians",
  standfirst:
    'The scandals that destroyed careers, toppled governments and shattered public trust.',
  publishedAt: '2026-06-22',
  authorByline: "The People's Chamber",
  body: [
    {
      type: 'heading',
      level: 2,
      text: 'John Profumo: The Man Who Taught Britain That the Cover-Up Is Worse Than the Sin',
    },
    {
      type: 'bioLine',
      text: 'Conservative · Secretary of State for War, 1960 to 1963 · Resigned from government, Parliament and the Privy Council on 5 June 1963 after admitting he had lied to the House of Commons.',
    },
    { type: 'paragraph', text: `Every generation produces a political scandal that becomes shorthand for something larger than the individuals involved. In the 1960s, that scandal was Profumo.` },
    { type: 'paragraph', text: `John Dennis Profumo was born on 30 January 1915 into a wealthy family of Italian origin. He was educated at Harrow and Oxford, served with distinction in the Second World War, was mentioned in despatches and ended the war as a brigadier. He entered Parliament in 1940 at the age of 25, making him one of the youngest MPs of his era. By 1960, Harold Macmillan had appointed him Secretary of State for War. He was married to Valerie Hobson, one of Britain's leading film actresses. The Profumos were at the centre of 1960s London society. Everything pointed upward.` },
    { type: 'paragraph', text: `On 8 July 1961, at a pool party at Cliveden, the Buckinghamshire estate of Lord Astor, Profumo was introduced to Christine Keeler by Stephen Ward. Ward was a society osteopath and socialite who moved between the aristocracy and the London demi-monde. Keeler was 19 years old, a former showgirl at a Soho nightclub whom Ward had taken under his wing. Also present at the party was Captain Yevgeny Ivanov, listed as a Soviet naval attache but known to MI5, through the double agent Oleg Penkovsky, as a GRU intelligence officer. Keeler was involved with both men. Profumo began a brief affair with her that ended by late 1961.` },
    { type: 'paragraph', text: `The affair might never have surfaced. In December 1962, a shooting incident outside Ward's London flat involving two other men connected to Keeler drew press attention. Reporters soon discovered her relationships with both the War Secretary and the Soviet intelligence officer. On 21 March 1963, Labour MP George Wigg, using parliamentary privilege to shield himself from libel, raised the rumours in the House of Commons. The next day, 22 March, Profumo stood before the House and made the statement that ended his career. He said there was "no impropriety whatsoever" in his acquaintanceship with Keeler. He threatened to issue writs for libel against anyone who repeated the allegations outside Parliament.` },
    { type: 'paragraph', text: `For ten weeks the denial held. Then the evidence became overwhelming. On 5 June 1963, Profumo admitted that he had lied to the House of Commons. He resigned from the government, from Parliament and from the Privy Council. His political career was over in a single day.` },
    { type: 'pullQuote', text: `He said there was "no impropriety whatsoever". Ten weeks later he admitted he had lied to the House of Commons.` },
    { type: 'paragraph', text: `The damage spread far beyond one man. Stephen Ward, the socialite who had introduced Profumo to Keeler, was charged with living off immoral earnings. Perceiving himself as a scapegoat for the powerful men whose secrets he had kept, Ward took a fatal overdose of sleeping pills on the last night of his trial. He died on 3 August 1963. His posthumous conviction was quashed in 2024 after a long campaign. The trial produced one of the most famous lines in British legal history, when Mandy Rice-Davies, Ward's friend, was told that Lord Astor denied having an affair with her. She replied: "Well, he would, wouldn't he?"` },
    { type: 'paragraph', text: `Lord Denning was appointed to conduct a judicial inquiry. His report, published on 26 September 1963, concluded that there had been no breach of national security arising from the Ivanov connection. The report was later criticised as superficial and unsatisfactory, and many felt it protected the establishment while allowing Ward to carry the blame.` },
    { type: 'paragraph', text: `Macmillan himself resigned as Prime Minister in October 1963, citing ill health. His successor, Alec Douglas-Home, led the Conservatives into the 1964 general election and lost to Harold Wilson's Labour. The affair had not caused the defeat on its own, but it had accelerated a sense of decay, entitlement and detachment that Macmillan's government could not shake.` },
    { type: 'paragraph', text: `What makes Profumo unique among disgraced politicians is what happened after the fall. In April 1964, he was invited to volunteer at Toynbee Hall, a charitable settlement in London's East End that worked with the most deprived communities in the city. He started by cleaning toilets. He had to be persuaded, and it was evidently a hard sell, to move from manual work into administration. Over the following four decades he served as administrator, fundraiser, council member, chairman and president of Toynbee Hall. He raised substantial funds and became central to the institution's work. In 1975, the Queen appointed him CBE for his charitable service. In 2003, he received the Beacon Fellowship Prize for combating social deprivation among London's working classes. Margaret Thatcher described him as a national hero and invited him to her 80th birthday celebration in 2005. Valerie Hobson, who had stood by him throughout the scandal, remained married to him until her death in 1998.` },
    { type: 'paragraph', text: `Profumo maintained complete public silence about the affair for the rest of his life. He never gave an interview. He never published a memoir. He never defended himself publicly. When the 1989 film Scandal revived interest in the story, he said nothing. He died on 9 March 2006, aged 91, at Chelsea and Westminster Hospital.` },
    { type: 'paragraph', text: `Many politicians have been caught lying. Very few turn the rest of their life into the answer. John Profumo lied to Parliament at the height of the Cold War, destroyed a government, and then spent 42 years cleaning toilets, raising money and rebuilding a life that owed nothing to status, power or public attention. That is why his name endures. Not because of the scandal, but because of the silence that followed it.` },

    {
      type: 'heading',
      level: 2,
      text: 'Jonathan Aitken: The Man Who Went to War With the Truth and Lost',
    },
    {
      type: 'bioLine',
      text: 'Conservative · Chief Secretary to the Treasury, 1994 to 1995 · MP for Thanet East, 1974 to 1997 · Jailed for 18 months in 1999 for perjury and perverting the course of justice.',
    },
    { type: 'paragraph', text: `Jonathan William Patrick Aitken was born on 30 August 1942 into the British political establishment. His father, Sir William Aitken, was a Conservative MP. His grandfather was the 1st Baron Rugby. His great-uncle was Lord Beaverbrook, the newspaper magnate and wartime minister. His sister is the actress Maria Aitken. His nephew is the actor Jack Davenport. He was educated at Eton and Christ Church, Oxford, then worked as a journalist before entering Parliament as MP for Thanet East in 1974. He served for 23 years. This was not a man who climbed the political ladder from obscurity. He was born on it.` },
    { type: 'paragraph', text: `By the early 1990s, Aitken's career was accelerating. He served as Minister of State for Defence Procurement, then in 1994 John Major appointed him Chief Secretary to the Treasury, a full Cabinet position. While at Defence Procurement, he was also a former director of BMARC, an arms exporter. In 1995, a Commons motion revealed that as a minister he had signed a Public Interest Immunity Certificate relating to the Matrix Churchill trial, suppressing documents that included material about arms supplies to Iraq by a company he had directed. The connection between his ministerial role and his commercial past was already uncomfortable before the scandal that would end his career.` },
    { type: 'paragraph', text: `In April 1995, The Guardian and Granada Television's World in Action accused Aitken of violating ministerial rules. The central allegation concerned a stay at the Ritz Hotel in Paris in September 1993, where an Arab business associate, Mohammed Said Ayas, a close associate of Prince Mohammed of Saudi Arabia, had paid his hotel bill. Aitken claimed his wife Lolicia had paid. The joint investigation also pointed to an arms deal involving Ayas and Saudi connections.` },
    { type: 'paragraph', text: `Aitken chose to fight. On 10 April 1995, he held a press conference outside the High Court and delivered the most famous statement of his career. He said he would use "the simple sword of truth and the trusty shield of British fair play" to defeat his accusers. It was intended to sound Churchillian. It became his epitaph.` },
    { type: 'pullQuote', text: `The simple sword of truth and the trusty shield of British fair play.` },
    { type: 'paragraph', text: `The libel case proceeded through 1996 and into 1997. Then the evidence arrived. British Airways records, airline vouchers and other documents proved that Lolicia Aitken had been in Switzerland, not in Paris, at the time she was supposed to have settled the Ritz bill. The defence collapsed. The case was abandoned on 20 June 1997. A few days later, World in Action broadcast a special edition. They titled it "The Dagger of Deceit." It was alleged that Aitken had been prepared to have his teenage daughter Victoria lie under oath to support his account, had the trial continued.` },
    { type: 'paragraph', text: `Aitken was charged with perjury and perverting the course of justice. On 8 June 1999, he pleaded guilty to both charges. He was sentenced to 18 months in prison and served seven. He was declared bankrupt, unable to pay legal costs estimated at £1.5 million. The Guardian was left unpaid. He resigned from the Privy Council, one of very few people ever to do so. He lost his marriage. Lolicia divorced him. In 1999, DNA testing confirmed that Petrina Khashoggi, the daughter of Soraya Khashoggi, former wife of the Saudi billionaire arms dealer Adnan Khashoggi, was Aitken's biological child from an earlier affair.` },
    { type: 'paragraph', text: `The destruction was total: career, Cabinet seat, Parliament, marriage, reputation, solvency and freedom, all gone. The man who had promised to fight with the sword of truth was undone by an airline voucher.` },
    { type: 'paragraph', text: `His downfall landed at the worst possible moment for John Major's government. The Conservatives were already battling accusations of sleaze, cronyism and ethical collapse. The Aitken case, alongside the cash-for-questions affair involving Neil Hamilton, became one of the defining images of a government that appeared to have lost its moral authority. The 1997 landslide that destroyed the Conservatives was fuelled in part by the sense that Westminster had rotted from the inside.` },
    { type: 'paragraph', text: `What happened next was not what anyone expected. In prison, Aitken attended the Alpha Course, studied the Bible, learned Greek and became a student of Christian theology at Wycliffe Hall, Oxford. He wrote two autobiographies: "Pride and Perjury" and "Porridge and Passion." He married his second wife, Elizabeth Harris, in 2003. In 2018, he was ordained as a deacon in the Church of England by the Bishop of London. In 2019, he was ordained as a priest. He now serves as a prison chaplain at Pentonville and as a non-stipendiary minister at St Matthew's Church, Westminster. He also wrote an award-winning biography of Richard Nixon, a subject choice that requires no further commentary.` },
    { type: 'paragraph', text: `A man who lied under oath, went to prison, lost everything and then became a prison chaplain at the jail where he himself might have served is either one of the great redemption stories of modern British politics or one of its most elaborate reinventions. The public can make its own judgement.` },
    { type: 'paragraph', text: `What is not in dispute is the lesson. Aitken's original offence, allowing a Saudi associate to pay a hotel bill, would probably have ended in resignation and embarrassment. Instead he chose to fight, to lie under oath, to involve his own daughter and to wrap the entire enterprise in the language of honour and fair play. The cover-up was worse than the sin. It always is.` },
    { type: 'paragraph', text: `Jonathan Aitken wanted to be remembered as the man who defeated his accusers. History remembers him as the man who challenged the truth to a fight and lost by his own hand.` },

    {
      type: 'heading',
      level: 2,
      text: "Jeffrey Archer: The Man Who Kept Escaping Scandal Until He Couldn't",
    },
    {
      type: 'bioLine',
      text: 'Conservative · Deputy Chairman of the Conservative Party, 1985 to 1986 · Life peer, Baron Archer of Weston-super-Mare · Jailed for four years in 2001 for perjury and perverting the course of justice.',
    },
    { type: 'paragraph', text: `Jeffrey Howard Archer was born on 15 April 1940 in Holloway, London, and grew up in Weston-super-Mare, Somerset. He won a scholarship to Wellington School, left with O-levels and later attended the Oxford University Department for Continuing Education for a Diploma of Education. He served as a Greater London Council councillor from 1967 to 1970, then entered Parliament as MP for Louth in Lincolnshire in 1969 at the age of 29. By 1974 he was nearly bankrupt after a catastrophic investment in a fraudulent company called Aquablast. He did not seek re-election. That might have been the end. Instead, he reinvented himself as a novelist. "Not a Penny More, Not a Penny Less" was published in 1976. "Kane and Abel" followed in 1979 and sold 34 million copies worldwide. His books have since sold more than 320 million copies. He became one of the bestselling authors in the world.` },
    { type: 'paragraph', text: `Margaret Thatcher appointed him Deputy Chairman of the Conservative Party in 1985. A year later, the News of the World published a story headlined "Tory boss Archer pays vice girl." The paper reported that Archer had paid £2,000 to Monica Coghlan, a sex worker, through an intermediary at Victoria Station. The payment was taped. It was never denied. What Archer denied was sleeping with her. Rival tabloid the Daily Star then went further, alleging that Archer had paid for sex. Archer resigned as Deputy Chairman and sued the Daily Star for libel.` },
    { type: 'paragraph', text: `The 1987 trial became one of the most famous libel cases in British legal history. Archer won £500,000 in damages. The trial judge, Mr Justice Caulfield, directed the jury with one of the most extraordinary remarks ever made from the bench. Speaking of Mary Archer, Jeffrey's wife and a distinguished Cambridge solar energy researcher, he asked: "Is she not elegant? Is she not fragrant? Would she have married a man who would consort with prostitutes?" The jury sided with Archer. Monica Coghlan was branded a liar. The Daily Star's editor, Lloyd Turner, was sacked six weeks later.` },
    { type: 'pullQuote', text: `Is she not elegant? Is she not fragrant? Would she have married a man who would consort with prostitutes?` },
    { type: 'paragraph', text: `For twelve years, it looked like the most successful libel action ever brought by a British politician. Archer was created a life peer in 1992, becoming Baron Archer of Weston-super-Mare. In 1999, he was selected as the first Conservative candidate for Mayor of London. Then the lie collapsed.` },
    { type: 'paragraph', text: `Ted Francis, a former friend who had provided a false alibi at the original trial, confessed to a newspaper that Archer had asked him to lie about their having dinner together on the night in question. Angela Peppiatt, Archer's former secretary, testified that he had given her a brand new diary and handwritten notes and told her to fabricate entries to create a false alibi. Peppiatt also testified that Archer had conducted a long-running affair with his former personal assistant Andrina Colquhoun and had regularly asked her to buy expensive presents for his girlfriends.` },
    { type: 'paragraph', text: `Archer was forced to withdraw from the mayoral race in November 1999. He was suspended from the Conservative Party for five years. On 26 September 2000, he was charged with perjury and perverting the course of justice.` },
    { type: 'paragraph', text: `Monica Coghlan did not live to see the trial. On 26 April 2001, a drug addict fleeing a pharmacy robbery crashed a stolen Jaguar into her Ford Fiesta outside Huddersfield. She lay in the wreckage for an hour. She died the next day in hospital, aged 50. She had said of Archer: "He took everything away from me. I lost my home, my dignity, my self respect, and any hope of a future." She never saw him convicted.` },
    { type: 'paragraph', text: `The trial opened at the Old Bailey in May 2001. Archer did not take the stand in his own defence. Mary Archer appeared in court daily to support him. His mother died during the trial. On 19 July 2001, the jury found him guilty of two counts of perjury and two counts of perverting the course of justice. Mr Justice Potts sentenced him to four years' imprisonment. The prosecution described him as "a man who, whatever successive allegation or obstacle he faced, his instinct and solution was to manipulate events and fabricate a dishonest answer."` },
    { type: 'paragraph', text: `He was sent first to Belmarsh, a Category A high security prison. He was later moved to Wayland in Norfolk, then to an open prison. He served approximately two years before release in 2003. He published three volumes of prison diaries: "Hell," "Purgatory" and "Heaven." The Daily Star issued proceedings to recover £2.2 million in damages, costs and interest.` },
    { type: 'paragraph', text: `Archer's downfall landed during the same era of Conservative sleaze that destroyed Jonathan Aitken and Neil Hamilton. Each case was different. Each confirmed the same public suspicion: that powerful men in Westminster believed the rules did not apply to them.` },
    { type: 'paragraph', text: `What distinguishes Archer from Aitken is the scale of the deception. He won £500,000 in libel damages from a newspaper that told the truth. He let a woman who told the truth be branded a liar. He fabricated diaries. He recruited friends to lie under oath. He was prepared, according to allegations that emerged, to have others continue lying had the original trial gone differently. And then he carried the lie for twelve years while collecting a peerage and a mayoral candidacy.` },
    { type: 'paragraph', text: `His books continue to sell. He retired from the House of Lords in 2024. His public profile never entirely disappeared.` },
    { type: 'paragraph', text: `But Monica Coghlan is dead. She never saw the verdict. She never heard the apology that never came. Jeffrey Archer wanted to be remembered as the man who defeated his accusers. History remembers him as the man who let a woman take the blame for a lie he told, and got away with it for twelve years until the truth came back.` },

    {
      type: 'heading',
      level: 2,
      text: 'Chris Huhne: The Cabinet Minister Who Threw Away His Career for Three Penalty Points',
    },
    {
      type: 'bioLine',
      text: 'Liberal Democrat · Secretary of State for Energy and Climate Change, 2010 to 2012 · MP for Eastleigh, 2005 to 2013 · The first Cabinet minister to resign as a direct result of criminal proceedings; jailed for eight months in 2013 for perverting the course of justice.',
    },
    { type: 'paragraph', text: `Christopher Paul Murray Huhne was born on 2 July 1954 in Westminster, London. He was educated at Westminster School, one of the most prestigious in the country, read PPE at Magdalen College, Oxford, and studied at the Sorbonne in Paris. He became a financial journalist, rose to European editor at The Economist, then moved into the City, building a personal fortune through property and financial services. He was elected as a Liberal Democrat MEP for South East England in 1999, then won the parliamentary seat of Eastleigh in 2005. He lost the Lib Dem leadership to Menzies Campbell in 2006, then lost again to Nick Clegg in 2007 by just 511 votes. Had a few hundred members voted differently, he might have become Deputy Prime Minister rather than Energy Secretary.` },
    { type: 'paragraph', text: `In May 2010, when the Coalition Government was formed, Clegg appointed Huhne Secretary of State for Energy and Climate Change. It was a Cabinet position at the centre of one of the most important policy areas in government. He was wealthy, well-connected and widely regarded as one of the Liberal Democrats' strongest performers.` },
    { type: 'paragraph', text: `On 12 March 2003, a BMW registered to Huhne was caught speeding on the M11 near Stansted Airport. The offence carried three penalty points. According to prosecutors, Huhne was already close to the limit on his licence. A nomination form was completed naming his wife, the Greek-born economist Vicky Pryce, as the driver. Pryce was at the time the Chief Economist at the Department for Business, Enterprise and Regulatory Reform, one of the most senior government economists in the country. The points went on her licence. The matter disappeared.` },
    { type: 'paragraph', text: `For seven years.` },
    { type: 'paragraph', text: `In June 2010, weeks after becoming Energy Secretary, Huhne left Pryce for his bisexual press adviser Carina Trimingham. The marriage collapsed. And Pryce decided the world should know about the penalty points.` },
    { type: 'paragraph', text: `In May 2011, Pryce approached a journalist at the Mail on Sunday, Andrew Alderson, with the story. She was helped by her friend and neighbour Constance Briscoe, a barrister and part-time judge. Together they initially claimed that one of Huhne's aides, Jo White, had taken the points on his behalf, before the true story emerged. Essex Police opened an investigation. A court order forced The Sunday Times to hand over a recording in which the former couple apparently discussed the points swap. Labour MP Simon Danczuk filed a criminal complaint.` },
    { type: 'paragraph', text: `On 3 February 2012, the Director of Public Prosecutions, Keir Starmer, announced there was sufficient evidence to charge both Huhne and Pryce with perverting the course of justice. Huhne immediately resigned from the Cabinet, becoming the first Cabinet minister in British history to resign as a direct result of criminal proceedings. He vowed to fight the charges.` },
    { type: 'paragraph', text: `He fought them for a year. On 4 February 2013, the first day of trial, he changed his plea to guilty. He resigned as MP for Eastleigh and left the Privy Council. The by-election that followed was won by the Liberal Democrats.` },
    { type: 'paragraph', text: `Pryce's trial began the next day. Her defence was marital coercion: she argued Huhne had pressured her into taking the points throughout their marriage, which she described as one of relentless control. She told the court he had demanded she have an abortion in 1990 because a baby would be bad for his career. The first jury was discharged after failing to reach a verdict. The judge remarked that the jury had "an absolutely fundamental deficit in understanding" of basic legal principles. A retrial convicted Pryce unanimously on 7 March 2013.` },
    { type: 'pullQuote', text: `An absolutely fundamental deficit in understanding of basic legal principles.` },
    { type: 'paragraph', text: `On 11 March 2013, Mr Justice Sweeney sentenced both Huhne and Pryce to eight months in prison. The judge rejected any suggestion that this was a minor matter. Huhne served nine weeks at HMP Leyhill, a Category D open prison in Gloucestershire, before being released.` },
    { type: 'paragraph', text: `Constance Briscoe, the barrister who had helped Pryce approach the press, was later convicted of three charges of perverting the course of justice for lying to police and falsifying evidence. She was jailed for 16 months and disbarred.` },
    { type: 'paragraph', text: `Years later, Huhne received six-figure damages from Rupert Murdoch's News Corporation after settling a claim that News Group newspapers had illegally gathered information about him, including through phone hacking. He argued he had been targeted because he had called for a reopening of the police investigation into hacking, the investigation that ultimately led to the prosecution and conviction of Andy Coulson, the former editor of the News of the World. That claim does not undo his guilty plea. It does add a layer of complication to a story the public thought was straightforward.` },
    { type: 'paragraph', text: `Three penalty points. One broken marriage. One Cabinet resignation. Two criminal convictions. One disbarred barrister. One destroyed political career. And a nine-week prison sentence.` },
    { type: 'paragraph', text: `Ordinary motorists accept points and fines every day. What made this case land was the perception that a Cabinet minister decided the rules were for other people. The original offence was trivial. The deception that followed it was not. The cover up, as always, was worse than the sin.` },
    { type: 'paragraph', text: `Chris Huhne possessed genuine political ability. He had reached Cabinet. He had come within 511 votes of leading his party. He had influence over energy policy at a time when energy security was becoming one of the defining issues in British politics. None of that is what he is remembered for. He is remembered for three points on a driving licence and the spectacular wreckage of trying to avoid them.` },

    {
      type: 'heading',
      level: 2,
      text: 'Denis MacShane: The MP Who Billed the Taxpayer With Fake Invoices',
    },
    {
      type: 'bioLine',
      text: "Labour · Minister of State for Europe, 2002 to 2005 · MP for Rotherham, 1994 to 2012 · Jailed for six months in 2013 for false accounting; the first former Labour minister imprisoned as a result of the expenses scandal.",
    },
    { type: 'paragraph', text: `Denis MacShane was born Josef Denis Matyjaszek on 21 May 1948 in Glasgow, the son of a Polish father and an Irish mother. His father died from war-related illness in 1958, when Denis was ten. He was educated on a Middlesex County scholarship at St Benedict's School in Ealing, read modern languages at Merton College, Oxford, then completed a PhD at Birkbeck, University of London. He worked as a BBC journalist, then as an official of the International Metalworkers' Federation in Geneva, before entering politics. He changed his name to MacShane. The man who would later fabricate invoices under a false name had already reinvented himself once.` },
    { type: 'paragraph', text: `He won the Rotherham by-election in 1994 and served as MP for 18 years. Tony Blair appointed him Minister of State for Europe at the Foreign Office in 2002, a post he held until 2005. He was one of Labour's most prominent pro-European voices and built a significant reputation in one area above all others: combating antisemitism. He chaired the All Party Parliamentary Group against Antisemitism, served as the Prime Minister's personal envoy on antisemitism, and chaired the European Institute for the Study of Contemporary Antisemitism. That work was widely respected. It also became the justification he offered for the fraud.` },
    { type: 'paragraph', text: `Between January 2005 and January 2008, MacShane submitted 19 fraudulent invoices to the parliamentary authorities. The invoices purported to come from an organisation called the European Policy Institute and claimed reimbursement for research and translation services. The total was £12,900.` },
    { type: 'paragraph', text: `There was no European Policy Institute in any meaningful sense. MacShane himself later described it as "a loose network" with "no office, no staff, and just a post box address." The Parliamentary Commissioner for Standards examined the invoices and concluded that MacShane had created them himself, signed them under a false name, and submitted them to claim public money. The Commissioner's verdict was blunt: "In effect, he was sending the invoice to himself and writing his own cheque."` },
    { type: 'pullQuote', text: `In effect, he was sending the invoice to himself and writing his own cheque.` },
    { type: 'paragraph', text: `He also claimed for eight laptop computers in three years.` },
    { type: 'paragraph', text: `The Standards and Privileges Committee reported in November 2012. MacShane resigned from Parliament the same day. In his resignation statement he said: "I have decided for the sake of my wonderful constituency of Rotherham and my beloved Labour Party to resign as an MP." He added: "I deeply regret that the way I chose to be reimbursed for costs related to my work in Europe and in combating antisemitism, including being the Prime Minister's personal envoy, has been judged so harshly."` },
    { type: 'paragraph', text: `The framing was revealing. He did not say the invoices were wrong. He said the judgement was harsh.` },
    { type: 'paragraph', text: `On 11 July 2013, the Crown Prosecution Service charged him with false accounting under the Theft Act 1968. On 18 November 2013, he pleaded guilty at the Old Bailey. On 23 December 2013, Mr Justice Sweeney sentenced him to six months in prison. He served his sentence at Belmarsh and Brixton before being released on an electronic tag after approximately four months. He resigned from the Privy Council.` },
    { type: 'paragraph', text: `His resignation triggered the Rotherham by-election, won by Sarah Champion for Labour in circumstances overshadowed by the simultaneous child sexual exploitation scandal that was then engulfing the town. MacShane's departure barely registered against the larger crisis.` },
    { type: 'paragraph', text: `The significance of the case extended beyond MacShane himself. The expenses scandal had already exposed claims for moat cleaning, duck houses, second homes and a catalogue of spending that left voters concluding Parliament operated by different rules. MacShane's conviction gave those suspicions a criminal dimension. He became the first former Labour minister imprisoned as a result of the scandal.` },
    { type: 'paragraph', text: `£12,900 is a small sum by the standards of political fraud. The damage was not the amount. It was the method. A Member of Parliament created fictitious invoices, signed them under a false name, submitted them to claim public money and framed the entire exercise as reimbursement for fighting antisemitism. The cause was real. The invoices were not. That distinction is what sent him to prison.` },
    { type: 'paragraph', text: `His speeches, campaigns and ministerial work on Europe and antisemitism have largely faded from memory. The fake invoices have not. A career built over decades was reduced to a guilty plea, a prison sentence and permanent association with the worst parliamentary expenses scandal in modern history.` },

    {
      type: 'heading',
      level: 2,
      text: 'Eric Illsley: The MP Who Billed the Taxpayer for a Home He Inflated',
    },
    {
      type: 'bioLine',
      text: 'Labour · MP for Barnsley Central, 1987 to 2011 · Jailed for 12 months in 2011 for false accounting; the first sitting MP convicted in the expenses scandal.',
    },
    { type: 'paragraph', text: `Eric Evlyn Illsley was born on 9 April 1955 in Barnsley, West Riding of Yorkshire. He was educated at Hunningley Lane Junior School and Holgate Grammar School for Boys in Barnsley before studying law at the University of Leeds, graduating with honours in 1977. When Roy Mason, the former Northern Ireland Secretary, retired from Barnsley Central in 1986, Illsley was nominated by the National Union of Mineworkers to replace him. He was selected in January 1987 and elected in June. He served on Labour's frontbench in opposition but was a backbencher after 1997. He represented Barnsley Central for 24 years.` },
    { type: 'paragraph', text: `The expenses scandal did not catch Illsley doing something complicated. It caught him doing something very simple, very often. Between May 2005 and April 2008, he was paid £39,204.25 in expenses for his second home at Dryden Court, Renfrew Road, Kennington, in south London. His actual costs amounted to approximately £25,000. He overclaimed by more than £14,000.` },
    { type: 'paragraph', text: `The method was crude. Until April 2008, MPs only needed receipts for claims over £250. Illsley systematically submitted claims just under that threshold for costs he had either not incurred or grossly inflated. His telephone bill for the London property came to between £34 and £36 per quarter. He claimed between £250 and £650 per quarter. When he submitted genuine invoices for the service charge on his flat, he added what prosecutors described as a "fictitious element" of false claims for maintenance. The pattern was consistent: real paperwork with fake numbers layered on top.` },
    { type: 'pullQuote', text: `He inflated his phone bill from £36 to £650, added fake maintenance costs to real invoices, and did it quarter after quarter for three years.` },
    { type: 'paragraph', text: `On 19 May 2010, days after being re-elected as Labour MP for Barnsley Central, he was charged with three counts of false accounting. The party suspended him. He sat as an independent. When interviewed by police earlier that year, he had handed over a prepared statement saying he had "at all times acted honestly."` },
    { type: 'paragraph', text: `On 11 January 2011, he pleaded guilty at Southwark Crown Court to all three charges. He became the first sitting Member of Parliament convicted of a criminal offence in the expenses scandal. David Chaytor had been convicted before him, but Chaytor had already left Parliament. Illsley was still an MP when the verdict came.` },
    { type: 'paragraph', text: `He resigned on 8 February 2011, taking the Chiltern Hundreds. Two days later, on 10 February, Mr Justice Saunders sentenced him to 12 months' imprisonment.` },
    { type: 'paragraph', text: `The judge's remarks stripped away any ambiguity. Parliament depended on public trust. The expenses system depended on honesty. Illsley had abused both. Wearing a charcoal suit, he picked up his overcoat and brown leather holdall, waved over his shoulder to a friend in the public gallery, and walked down to the cells.` },
    { type: 'paragraph', text: `The by-election that followed produced one of the more consequential results of recent British politics. Dan Jarvis, a former Major in the Parachute Regiment and Special Forces Support Group who had lost his first wife to cancer the year before, won Barnsley Central. Fifteen years later, Jarvis is the Secretary of State for Defence. The seat Illsley disgraced became the launchpad for one of the most decorated military careers in modern parliamentary history.` },
    { type: 'paragraph', text: `The expenses scandal had already exposed duck houses, moat cleaning, second home flipping and a catalogue of claims that left voters concluding Westminster operated by its own rules. Illsley's conviction gave those conclusions a criminal stamp. He was not the most senior MP caught. He was not the largest claimant. What made his case cut through was the simplicity of it. A man inflated his phone bill from £36 to £650, added fake maintenance costs to real invoices, and did it quarter after quarter for three years. The public did not need a lawyer to understand that. They understood it immediately.` },
    { type: 'paragraph', text: `Twenty four years in Parliament. Three counts of false accounting. Twelve months in prison. And a successor who went on to become Defence Secretary.` },
    { type: 'paragraph', text: `For Eric Illsley, the epitaph writes itself.` },

    {
      type: 'heading',
      level: 2,
      text: 'Charlie Elphicke: The MP Who Went From Westminster to a Prison Cell',
    },
    {
      type: 'bioLine',
      text: 'Conservative · Government Whip and Lord Commissioner of the Treasury, 2015 to 2016 · MP for Dover, 2010 to 2019 · Jailed for two years in 2020 for three counts of sexual assault.',
    },
    { type: 'paragraph', text: `Charles Brett Anthony Elphicke was born on 14 March 1971. He studied law at the University of Nottingham, then worked as a solicitor and tax adviser in the City of London. He was selected as the Conservative candidate for Dover in 2007 and won the seat at the 2010 general election with a 10.4 percent swing from Labour, the 31st largest in the country. He was energetic on immigration, border controls and the Port of Dover. From 2015 to 2016 he served as a Government Whip and Lord Commissioner of the Treasury. He held office in government. That makes what followed worse.` },
    { type: 'paragraph', text: `In November 2017, during the wider wave of misconduct allegations shaking Westminster, the Conservative Party suspended Elphicke. He said he was "not aware of what the alleged claims are" and denied wrongdoing. His wife Natalie immediately defended him, calling his suspension "a threat to British values." In March 2018 he was told the accusations were sex offences against two women connected to his work.` },
    { type: 'paragraph', text: `Then the party made its most damaging decision. In December 2018, facing a confidence vote in Theresa May's leadership, the Conservatives reinstated Elphicke's whip. A man under investigation for sexual assault had his party membership restored so he could vote to keep the Prime Minister in office. After the vote, the whip was withdrawn again. The party's judgement was that one vote on one evening was worth the signal it sent about how seriously it took the allegations.` },
    { type: 'pullQuote', text: `A man under investigation for sexual assault had his party membership restored so he could vote to keep the Prime Minister in office.` },
    { type: 'paragraph', text: `In July 2019, the Crown Prosecution Service charged Elphicke with three counts of sexual assault against two women. The offences allegedly took place in 2007 and 2016. He did not stand for re-election. His wife Natalie was selected as the Conservative candidate to succeed him in Dover. She was the only name on the ballot. She won the seat with a majority of 12,278.` },
    { type: 'paragraph', text: `The trial took place at Southwark Crown Court in July 2020. The court heard that Elphicke had assaulted two women on separate occasions, one in his Westminster home and the other after what she described as a sustained campaign of unwanted advances. His defence argued he was "an affectionate person." On 30 July 2020, the jury found him guilty on all three counts.` },
    { type: 'paragraph', text: `On the day of the verdict, Natalie Elphicke confirmed on Twitter that their 25 year marriage was over. Days later, she reversed course and publicly defended him, saying he had been punished for being "charming, wealthy, charismatic and successful, attractive, and attracted, to women" and dismissing the accounts of his victims. It later emerged that she had lobbied Robert Buckland, the Justice Secretary, over her husband's court case. In July 2021, she and four other MPs were found by the Commons Standards Committee to have breached their code of conduct by attempting to influence senior judges during his sentencing appeal.` },
    { type: 'paragraph', text: `On 15 September 2020, Mrs Justice Whipple sentenced Elphicke to two years in prison. She rejected attempts to portray the offences as misunderstandings. She concluded he had acted as though he was entitled to behave as he wished towards women and had abused positions of trust and influence. His application for leave to appeal was refused in March 2021. He served half his sentence at HMP Leyhill before being released on 14 September 2021.` },
    { type: 'paragraph', text: `After release, he told a court that he was living in a rented one bedroom flat, claiming Universal Credit, and described himself as having "no job, no career" and being "long term unemployed." He was nonetheless ordered to pay £35,000 towards prosecution costs within a year.` },
    { type: 'paragraph', text: `The political aftermath continued. In May 2024, Natalie Elphicke defected from the Conservatives to Labour, crossing the floor moments before Prime Minister's Questions. The following day she apologised for defending her former husband and casting doubt on his victims' testimonies. Steve Baker, a Conservative minister, commented that he had been "searching in vain for a Conservative MP who thinks themself to the right of Natalie Elphicke." Labour's Momentum described her as having "no place" in a party "committed to progressive values." She stood down at the 2024 general election.` },
    { type: 'paragraph', text: `Charlie Elphicke's conviction was not a parliamentary expenses fiddle or a lobbying scandal. It was a criminal conviction for sexual assault, delivered by a jury, producing a two year prison sentence. A Government Whip whose party reinstated him to win a confidence vote, whose wife succeeded him in his seat, and whose victims were told he was merely being "charming." The case demonstrated that criminal allegations against MPs could produce the same consequences faced by anyone else. It also demonstrated that the political system around the defendant could still attempt to minimise, manage and instrumentalise the allegations for as long as it was politically useful to do so.` },

    {
      type: 'heading',
      level: 2,
      text: 'Owen Paterson: The MP Who Turned Parliament Into a Lobbying Firm',
    },
    {
      type: 'bioLine',
      text: `Conservative · Northern Ireland Secretary, 2010 to 2012 · Environment Secretary, 2012 to 2014 · MP for North Shropshire, 1997 to 2021 · Resigned in 2021 after the Standards Commissioner found "an egregious case of paid advocacy".`,
    },
    { type: 'paragraph', text: `Owen William Paterson was born on 24 June 1956 in Whitchurch, Shropshire, and grew up on the family farm. He was educated at Abberley Hall, Radley College and Corpus Christi College, Cambridge, where he read History. He speaks French and German fluently. He joined the family business, the British Leather Company, in 1979, became Sales Director at 27, Managing Director at 37, and served as President of the European Tanners' Confederation from 1996 to 1998. He entered Parliament as MP for North Shropshire in 1997 and held the seat with commanding majorities for 24 years. He served as Shadow Northern Ireland Secretary (2007 to 2010), Northern Ireland Secretary (2010 to 2012) and Environment Secretary (2012 to 2014) before being dismissed by David Cameron in the 2014 reshuffle and replaced by Liz Truss.` },
    { type: 'paragraph', text: `The consultancies began after he left government. From 2015, Paterson was paid £8,333 per month by Randox Laboratories, a clinical diagnostics company based in Northern Ireland, for 16 hours of work per month. That is £100,000 per year. From 2016, he also received £12,000 per year from Lynn's Country Foods, a Northern Ireland sausage manufacturer, for 24 hours of work. Combined: over £112,000 a year from two companies while serving as a Member of Parliament.` },
    { type: 'paragraph', text: `The Parliamentary Commissioner for Standards, Kathryn Stone, found that Paterson had made 14 approaches to ministers, officials and regulatory bodies on behalf of those companies between 2016 and 2020. Three approaches to the Food Standards Agency and four to the Department for International Development were on behalf of Randox. Seven approaches to the Food Standards Agency were on behalf of Lynn's Country Foods. The Commissioner concluded that Paterson had engaged in "an egregious case of paid advocacy" and that "no previous case of paid advocacy has seen so many breaches or such a clear pattern of confusion between the private and public interest." The Standards Committee recommended a 30 day suspension from the House of Commons.` },
    { type: 'paragraph', text: `The Covid contracts made the story radioactive. In March 2020, Randox was awarded a £133 million contract from the Department of Health and Social Care to produce testing kits during the pandemic, without any other company being given the opportunity to bid. Six months later, Randox received a further £347 million contract, again without competition. In April 2020, Paterson represented Randox in a call with James Bethell, the minister responsible for awarding contracts to the private sector during the pandemic. The government was later unable to find any minutes of that meeting. A company paying its consultant MP £100,000 a year received £480 million in public contracts without competitive tender during a national emergency. Paterson maintained throughout that he was raising legitimate public health concerns.` },
    { type: 'pullQuote', text: `A company paying its consultant MP £100,000 a year received £480 million in public contracts without competitive tender during a national emergency.` },
    { type: 'paragraph', text: `Rose Paterson, Owen's wife, died by suicide in June 2020 while the investigation was ongoing. She had served as Chair of Aintree Racecourse. Paterson said the investigation had contributed to her death and accused the Commissioner of making up her mind before speaking to him. He later established The Rose Paterson Trust in her memory.` },
    { type: 'paragraph', text: `On 3 November 2021, Boris Johnson's government whipped Conservative MPs to vote for an amendment, tabled by Andrea Leadsom, that would overturn the Standards Committee's recommendation and create a new committee to review the disciplinary process. The vote passed 250 to 232. The backlash was immediate and ferocious. Newspapers accused the government of rewriting the rules to protect a political ally. Conservative MPs reported furious reactions from constituents. Within 24 hours Downing Street was retreating. On 4 November, the government abandoned the plan. On 5 November, Paterson resigned.` },
    { type: 'paragraph', text: `In his resignation statement he said: "The last two years have been an indescribable nightmare for my family and me. I maintain that I am totally innocent of what I have been accused of and I acted at all times in the interests of public health and safety." On 16 November, Parliament passed a motion accepting the original findings.` },
    { type: 'paragraph', text: `The North Shropshire by-election on 16 December 2021 was devastating. Helen Morgan, the Liberal Democrat candidate, won with a majority of 5,925, overturning a Conservative majority of 22,949. It was the first time the seat had returned a non-Conservative MP in over 100 years. The Conservative candidate was Neil Shastri-Hurst, a trauma surgeon, barrister and Army Major who would later win Solihull West and Shirley at the 2024 general election. Several ministers who resigned during the later collapse of Johnson's premiership cited the government's handling of the Paterson scandal in their resignation letters.` },
    { type: 'paragraph', text: `Paterson subsequently took legal action against the British government at the European Court of Human Rights, arguing that the parliamentary investigation had been unfair. That a Eurosceptic Conservative who spent years opposing European jurisdiction over British affairs chose the ECHR as his forum for appeal was an irony nobody needed pointing out.` },
    { type: 'paragraph', text: `£112,000 a year from two companies. Fourteen breaches of lobbying rules. £480 million in untendered Covid contracts to one of those companies. A government attempt to rewrite the rules to protect him. A resignation. A by-election that ended a century of Conservative dominance. And one word from an official finding that no political career survives.` },
    { type: 'paragraph', text: `"Egregious."` },
    { type: 'paragraph', text: `Owen Paterson never recovered from it. Few politicians ever would.` },

    {
      type: 'heading',
      level: 2,
      text: 'Chris Pincher: The MP Who Brought Down a Prime Minister',
    },
    {
      type: 'bioLine',
      text: `Conservative · Deputy Chief Whip (twice) and Minister of State · MP for Tamworth, 2010 to 2023 · Resigned in 2023 after groping two men at the Carlton Club; the scandal triggered the fall of Boris Johnson's government.`,
    },
    { type: 'paragraph', text: `Christopher John Pincher served as Conservative MP for Tamworth from 2010 until 2023. He first contested the seat in 2005. He rose through the party's internal machinery: PPS to Foreign Secretary Philip Hammond, then Comptroller of the Household, then Deputy Chief Whip and Treasurer of the Household, then Minister of State for Europe and the Americas, then Minister of State for Housing, and back to Deputy Chief Whip. He was appointed to the Privy Council in 2018. That career path tells one story. The record beneath it tells another.` },
    { type: 'paragraph', text: `In November 2017, as part of the wider Westminster sexual misconduct crisis, two men made allegations against Pincher. Former Olympic rower and Conservative candidate Alex Story accused him of making an unwanted sexual advance. Labour MP Tom Blenkinsop accused him of unwanted sexual contact. Pincher resigned as assistant whip and referred himself to the party complaints process and the police. Two months later, in January 2018, Theresa May reappointed him as Government Deputy Chief Whip. He was promoted, not removed.` },
    { type: 'paragraph', text: `In 2019, a complaint was upheld relating to Pincher's conduct towards a Foreign Office official. It resulted in a formal apology. Boris Johnson was personally briefed about this by Simon McDonald, the Permanent Secretary at the Foreign Office. In February 2022, Johnson appointed Pincher Deputy Chief Whip for the second time. The man responsible for the welfare and discipline of Conservative MPs had known allegations of sexual misconduct spanning years. The party and two Prime Ministers kept putting him back.` },
    { type: 'pullQuote', text: `The question was never whether Westminster knew about Chris Pincher. The question was why Westminster kept putting him in charge of other people's welfare.` },
    { type: 'paragraph', text: `On the evening of 29 June 2022, Pincher attended the Carlton Club, the historic Conservative members' club in central London. According to the subsequent investigation, while heavily intoxicated he groped two men, touching one on the arm, neck and bottom, and the other on the testicles. The following day he resigned as Deputy Chief Whip, acknowledging that he had "drunk far too much" and "embarrassed myself and other people."` },
    { type: 'paragraph', text: `Within days, six further allegations emerged involving behaviour over a decade. Three complaints described unwanted advances against male MPs, one in a bar at the House of Commons and one in Pincher's parliamentary office. Daniel Cook, the Conservative deputy mayor of Tamworth, said publicly that Pincher had sexually assaulted him in 2005 and 2006. One complainant said he had provided details to Downing Street in February 2022, before Pincher's reappointment, and had expressed concerns about a man with known allegations being placed in charge of other MPs' welfare.` },
    { type: 'paragraph', text: `Assistant Government Whip Sarah Dines, in a meeting with one of the Carlton Club victims, asked him about his sexuality. When he replied "What's that got to do with it? But yes, I am," she responded: "Well, that doesn't make it straightforward."` },
    { type: 'paragraph', text: `The government's account of what Johnson knew changed repeatedly. First, Downing Street said the Prime Minister had not been aware of specific allegations. Then officials admitted concerns had been raised. Then Lord McDonald, the former Permanent Secretary at the Foreign Office, wrote to the Parliamentary Commissioner for Standards stating that Johnson had been personally briefed about the 2019 complaint. The letter made the denials untenable.` },
    { type: 'paragraph', text: `The story stopped being about Chris Pincher and became about whether the Prime Minister had lied.` },
    { type: 'paragraph', text: `Between 5 and 7 July 2022, the government collapsed from within. Sajid Javid resigned first. Rishi Sunak followed. More ministers resigned on 6 July alone than on any single day in parliamentary history. By the middle of 7 July, 60 resignations had been submitted, 30 by ministers. Michael Gove was dismissed. On 7 July 2022, Boris Johnson announced his resignation as Conservative leader. He remained in office until 6 September, when Liz Truss succeeded him.` },
    { type: 'paragraph', text: `The Standards Committee published its report on 6 July 2023. It concluded that Pincher had caused "significant damage" to the reputation of Parliament and had abused his position of authority as a senior whip. The committee recommended an eight week suspension. Pincher appealed. On 4 September 2023, the appeal was rejected. On 7 September 2023, he resigned as an MP, triggering the Tamworth by-election. Labour won the seat, overturning the Conservative majority.` },
    { type: 'paragraph', text: `The pattern is what makes this scandal distinct from the others. Pincher was not a politician who concealed his behaviour until it was suddenly exposed. Allegations were known in 2017. A complaint was upheld in 2019. A briefing was given to the Prime Minister. A further warning was delivered to Downing Street in February 2022. At every stage, the system was informed. At every stage, Pincher was promoted. He served as Deputy Chief Whip twice, held two ministerial posts and received a Privy Council appointment after the first set of allegations became public. The question was never whether Westminster knew about Chris Pincher. The question was why Westminster kept putting him in charge of other people's welfare.` },
    { type: 'paragraph', text: `Chris Pincher did not bring down a Prime Minister on his own. Johnson was already weakened by Partygate, the Owen Paterson affair and a series of credibility crises. But the Pincher scandal was the one that broke the dam, because it was the one where the lie was provable: Johnson said he did not know. Lord McDonald said he did. Sixty resignations later, the government was gone.` },
    { type: 'paragraph', text: `Most disgraced politicians destroy their own careers. Chris Pincher managed to take the government with him. That is not an achievement. But it is a fact that will outlast everything else he ever did.` },

    {
      type: 'heading',
      level: 2,
      text: 'John Stonehouse: The Minister Who Faked His Own Death',
    },
    {
      type: 'bioLine',
      text: `Labour and Co-operative · Postmaster General, 1968 to 1969 · MP for Wednesbury then Walsall North, 1957 to 1976 · Faked his own death in 1974, fled to Australia under stolen identities, and was later confirmed to have spied for Czechoslovak intelligence.`,
    },
    { type: 'paragraph', text: `John Thomson Stonehouse was born on 28 July 1925 in Southampton. He was educated at Taunton's School and the London School of Economics, where he took a BSc in Economics. He entered Parliament as Labour and Co-operative MP for Wednesbury in 1957, aged 32. Over the next 13 years he held a succession of government posts: Parliamentary Under-Secretary for the Colonies, Minister of Aviation, Postmaster General (1968 to 1969) and Minister of State for Technology. By 1970, he was considered a serious figure with ambitions for higher office.` },
    { type: 'paragraph', text: `Then Harold Wilson lost the 1970 election and Stonehouse lost his ministerial salary. He was not appointed to the Shadow Cabinet. To supplement his MP's pay he set up a series of import/export companies. By 1974, every one of them was in financial trouble. The Department of Trade and Industry was investigating. Debts were mounting.` },
    { type: 'paragraph', text: `There was also Sheila Buckley.` },
    { type: 'paragraph', text: `Buckley was Stonehouse's secretary and his mistress. The plan was not simply to escape his debts. It was to start a new life with her on the other side of the world. To do this, he needed to become someone else. He chose two identities, both stolen from dead constituents: Joseph Markham and Clive Mildoon. Secret government documents declassified in 2005 showed that Stonehouse had spent months rehearsing the Markham identity before the disappearance.` },
    { type: 'paragraph', text: `On 20 November 1974, Stonehouse checked into the Fontainebleau Hotel in Miami. That afternoon he told a business colleague he was going for a swim. He left his clothes with the beach cabana attendant. In his hotel room he left behind his briefcase, chequebooks, more than $800 in cash and travellers' cheques, his driving licence and his credit cards. Everything pointed to a man who had gone into the sea and never come back. He had not. He had walked along the coast, changed into dry clothes he had pre-positioned at a different hotel and caught a flight to Australia, 9,000 miles away, to begin a new life.` },
    { type: 'paragraph', text: `Obituaries were drafted. Tributes were prepared. His family, colleagues and constituents believed he was dead. His wife Barbara and their three children grieved.` },
    { type: 'paragraph', text: `In Melbourne, Stonehouse deposited A$21,500 in cash at the Bank of New Zealand under the name Clive Mildoon. The same bank teller later spotted him at the Bank of New South Wales and discovered a second account in the name Joseph Markham. The teller contacted the police. Australian authorities placed Stonehouse under surveillance. They initially suspected he might be Lord Lucan, who had disappeared two weeks earlier after the murder of his children's nanny. When they arrested him on 24 December 1974, Christmas Eve, they ordered him to pull down his trousers to check for a scar on his thigh that would identify Lucan. He did not have it. He was not Lord Lucan. He was something arguably stranger: a British Member of Parliament who had faked his own death.` },
    { type: 'pullQuote', text: `He was not Lord Lucan. He was something arguably stranger: a British Member of Parliament who had faked his own death.` },
    { type: 'paragraph', text: `The legal proceedings lasted years. Stonehouse was charged with fraud, theft and deception. The trial at the Old Bailey began in June 1976 and lasted 68 days. He represented himself because he could not afford a solicitor. He was found guilty and sentenced to seven years. Sheila Buckley was convicted separately and received a suspended sentence.` },
    { type: 'paragraph', text: `The most extraordinary detail is that Stonehouse continued to sit as a Member of Parliament throughout the entire period between his arrest and his conviction. He lost the Labour whip, briefly represented something called the English National Party, then sat as an independent. He finally resigned his seat after the guilty verdict. His constituents in Walsall North had been represented for two years by a man who had faked his own death, been arrested in Australia, and was standing trial at the Old Bailey.` },
    { type: 'paragraph', text: `In prison he suffered three heart attacks and underwent open heart surgery lasting six hours. He was released in August 1979 on grounds of ill health after serving roughly three years. He divorced Barbara and married Sheila Buckley. He joined the SDP. He wrote four novels. He appeared on television and radio discussing his disappearance. He died on 14 April 1988, aged 62.` },
    { type: 'paragraph', text: `There is a final dimension to the Stonehouse story that did not become fully clear until decades later. In 1969, Harold Wilson was informed by MI5 that a defector from the Czechoslovak intelligence service, the StB, had named Stonehouse as a spy. Wilson confronted him. Stonehouse denied it. In 2009, the official history of MI5, "The Defence of the Realm" by Cambridge historian Christopher Andrew, substantiated the allegation. Stonehouse had spied for Czechoslovak intelligence for at least 12 years while serving as a Member of Parliament and government minister. He received approximately £5,000, equivalent to roughly £70,000 in current money. In 2010 it emerged that Margaret Thatcher's government had agreed in 1980 to suppress the evidence because it was insufficient for a criminal prosecution.` },
    { type: 'paragraph', text: `A Labour minister. A spy for a communist state. A fraudster. A bigamist in all but law. A man who faked his own death, stole the identities of dead constituents, fled to Australia with his mistress, was mistaken for a suspected murderer, represented himself at a 68 day trial and continued sitting in Parliament while on bail for fraud.` },
    { type: 'paragraph', text: `Even by the standards of British political scandal, John Stonehouse occupies a category of his own.` },

    {
      type: 'heading',
      level: 2,
      text: 'What These Ten Men Got Wrong',
    },
    {
      type: 'bioLine',
      text: `The common thread running through Britain's biggest political disgraces.`,
    },
    { type: 'paragraph', text: `The scandals are different. One involved sex. Another involved lobbying. Several involved prison sentences. Some centred on lies, others on money, others on abuse of power.` },
    { type: 'paragraph', text: `Yet the same pattern appears again and again.` },
    { type: 'pullQuote', text: `The cover up was worse than the sin. It always is.` },
    { type: 'paragraph', text: `John Profumo stood before the House of Commons on 22 March 1963 and said there was "no impropriety whatsoever" in his relationship with Christine Keeler. There was.` },
    { type: 'paragraph', text: `Jonathan Aitken stood before the cameras on 10 April 1995 and promised to fight The Guardian with "the simple sword of truth." His wife was in Switzerland, not at the Ritz in Paris where he claimed. British Airways had the records.` },
    { type: 'paragraph', text: `Jeffrey Archer won £500,000 in libel damages from a newspaper that told the truth. He fabricated diaries. He recruited a friend to provide a false alibi. He let Monica Coghlan be branded a liar. She died in a car crash in 2001 without ever seeing his conviction.` },
    { type: 'paragraph', text: `Chris Huhne, a Cabinet minister 511 votes from leading his party, arranged for his wife to accept three penalty points on his licence. He denied it for years. He changed his plea on the first day of trial. He served nine weeks in prison.` },
    { type: 'paragraph', text: `Denis MacShane, born Josef Denis Matyjaszek, created invoices from an organisation that had no office, no staff and no existence, signed them under a false name and submitted them to claim £12,900 in public money. The Parliamentary Commissioner said he was "sending the invoice to himself and writing his own cheque."` },
    { type: 'paragraph', text: `Eric Illsley inflated his phone bill from £36 a quarter to as much as £650, added fictitious maintenance claims to genuine invoices and did it quarter after quarter for three years. His actual expenses were £25,000. He claimed £39,204.` },
    { type: 'paragraph', text: `Owen Paterson received £112,000 a year from two companies while sitting as an MP, made 14 approaches to ministers and officials on their behalf, and watched one of those companies receive £480 million in untendered Covid contracts. The government tried to rewrite the rules to protect him. The vote was 250 to 232 before the backlash forced a reversal within 24 hours. North Shropshire elected its first non-Conservative MP in over 100 years.` },
    { type: 'paragraph', text: `Charlie Elphicke, a Government Whip, was convicted of three counts of sexual assault. His party had reinstated his whip during a sexual assault investigation specifically to secure his vote in a confidence motion. After release he described himself as having "no job, no career," living in a rented one bedroom flat and claiming Universal Credit.` },
    { type: 'paragraph', text: `Chris Pincher was appointed Deputy Chief Whip despite Boris Johnson having been personally briefed about a previous upheld complaint of sexual misconduct. When Pincher groped two men at the Carlton Club, the question was not just what he had done. It was why Johnson had put him there. Sixty ministers resigned. The government fell.` },
    { type: 'paragraph', text: `John Stonehouse faked his own death on a Miami beach, fled to Australia under the stolen identities of two dead constituents, was arrested on Christmas Eve, represented himself across a 68 day trial, sat in Parliament throughout, and was later confirmed to have spied for Czechoslovak intelligence for twelve years.` },
    { type: 'paragraph', text: `The details vary. The underlying mistake rarely does.` },
    { type: 'paragraph', text: `Each man reached a point where the ordinary rules stopped applying. That is the real lesson of political disgrace. Most voters do not expect politicians to be saints. They never have. British political history is littered with affairs, arguments, betrayals and personal failings. What voters find harder to forgive is the belief that powerful people deserve different treatment from everyone else.` },
    { type: 'paragraph', text: `Profumo might have survived an affair. He did not survive the lie to the House.` },
    { type: 'paragraph', text: `Huhne might have survived a speeding ticket. He did not survive asking his wife to take the points.` },
    { type: 'paragraph', text: `Paterson might have survived outside earnings. He did not survive £480 million in contracts going to his client without competitive bidding.` },
    { type: 'paragraph', text: `Archer might have survived embarrassment. He did not survive fabricating an alibi and letting a woman take the blame for 14 years.` },
    { type: 'paragraph', text: `Stonehouse might have survived his debts. He did not survive faking his own death to escape them.` },
    { type: 'paragraph', text: `What destroyed each of them was not the original offence. It was the decision to use power, influence, status or deception to escape the consequences. The cover up was worse than the sin. It always is.` },
    { type: 'paragraph', text: `Several of these men were talented politicians. Profumo was Secretary of State for War. Aitken was Chief Secretary to the Treasury. Huhne was Energy Secretary. Paterson served as Northern Ireland Secretary and Environment Secretary. Their combined ministerial experience ran to decades. Almost nobody remembers any of it now.` },
    { type: 'paragraph', text: `Instead they are remembered for a lie, a claim form, a court case, a forged diary, a fabricated invoice, a taped payment at Victoria Station, three penalty points, a grope at the Carlton Club and a £500,000 libel verdict that turned out to be the biggest fraud of the lot.` },
    { type: 'paragraph', text: `Political careers are built over decades. Political disgrace arrives in a single headline. That is the brutal arithmetic of public life. The higher the office, the greater the fall. For these ten men, the fall was all anyone remembers.` },
  ],
};

export default piece;
